import{_ as e,o as s,c as n,a3 as t}from"./chunks/framework.1Y430-yj.js";const m=JSON.parse('{"title":"1.2 What Are the Benefits of Blocking-Based Production?","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"1\\\\.2 采用阻塞生产形式有什么好处","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=vjw47WlrDGyaYlemKyfnH8","scope":"page"}},"headers":[],"relativePath":"logistics/src/page-vjw47WlrDGyaYlemKyfnH8.md","filePath":"logistics/src/page-vjw47WlrDGyaYlemKyfnH8.md","lastUpdated":null}'),r={name:"logistics/src/page-vjw47WlrDGyaYlemKyfnH8.md"};function l(p,a,o,i,c,u){return s(),n("div",null,[...a[0]||(a[0]=[t('<div class="logistics-content"><span class="logistics-source-anchor" id="_1-2-采用阻塞生产形式有什么好处" aria-hidden="true"></span><h1 id="_1-2-what-are-the-benefits-of-blocking-based-production" tabindex="-1">1.2 What Are the Benefits of Blocking-Based Production? <a class="header-anchor" href="#_1-2-what-are-the-benefits-of-blocking-based-production" aria-label="Permalink to &quot;1\\.2 What Are the Benefits of Blocking-Based Production?&quot;">​</a></h1><blockquote><p>Source page ID: <code>vjw47WlrDGyaYlemKyfnH8</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=vjw47WlrDGyaYlemKyfnH8" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Compared with conventional fixed-rate production, a well-designed blocking-based line greatly simplifies advanced requirements. For example:</p><ol><li><p><span class="mark-purple">I want to produce </span><span class="mark-purple"><u>a depot full of Amethyst Bottles</u></span><span class="mark-purple"> before beginning </span><span class="mark-purple"><u>Cryston Bottles</u></span><span class="mark-purple">.</span></p></li><li><p><span class="mark-purple">I want </span><span class="mark-purple"><u>Steel Parts always available in the depot</u></span><span class="mark-purple"> without wasting Steel capacity while they are unused: everything goes to Valley Batteries instead.</span></p></li><li><p><span class="mark-purple">I want Cuprium to </span><span class="mark-purple"><u>make Cuprium Parts first</u></span><span class="mark-purple">. To prevent full Cuprium storage blocking Sewage, once parts fill up, </span><span class="mark-purple"><u>Cuprium should continue making Cuprium Components</u></span><span class="mark-purple">.</span></p></li><li><p><span class="mark-purple">I want Xiranite to </span><span class="mark-purple"><u>satisfy SC Wuling Battery production first</u></span><span class="mark-purple">, using the remainder elsewhere, so even occasional extra Originium Powder brought from the Valley is consumed.</span></p></li><li><p><span class="mark-purple">I want to </span><span class="mark-purple"><u>turn every input into finished products</u></span><span class="mark-purple">. Even complicated fractional production rates can be reached automatically through adaptation.</span></p></li><li><p><span class="mark-purple">I do not want transmuters freeloading on Xiranite: supply it according to available inputs.</span></p></li></ol><p>Conventional direct production often needs manual adjustments, such as machine production configuration, for these common advanced demands. Besides inconvenience, forgotten operations or inability to log in at the right time may waste materials or even cause outages. Specific blocking-based designs switch production automatically, achieving these goals without intervention and reducing our operational burden.</p><p><a href="./page-quUTb9JSv879txqKEKI0BS">1.1 So Tell Me: What Is Production Controlled by Blocking?</a></p><p><a href="./page-FBJt940VrXTDHkr5w3g0v3">1.3 Glossary (Even I Cannot Fully Define These; You Can Skip It)</a></p></div>',1)])])}const g=e(r,[["render",l]]);export{m as __pageData,g as default};
